  .stat-lbl {{ font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 1px; margin-top: 4px; }}

  /* Annotation labels */
  .annotation-labels {{ display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }}
  .ann-label {{
    font-size: 11px; padding: 3px 9px;
    border-radius: 4px; background: var(--surface2);
    border: 1px solid var(--border); color: var(--text-muted);
  }}
  .ann-label span {{ font-weight: 600; margin-right: 4px; }}

  /* Footer */
  .report-footer {{
    background: var(--surface);
    border-top: 1px solid var(--border);
    padding: 24px 40px;
    text-align: center;
    font-size: 12px;
    color: var(--text-muted);
  }}

  /* TOC / nav */
  .toc {{ display: flex; gap: 8px; flex-wrap: wrap; padding: 16px 0; margin-bottom: 8px; }}
  .toc a {{
    font-size: 12px; color: var(--text-muted); text-decoration: none;
    padding: 4px 12px; border: 1px solid var(--border); border-radius: 20px;
    transition: all 0.2s;
  }}
