      <div class="chart-wrap" style="height:240px;">
        <canvas id="chartRollStd"></canvas>
      </div>
    </div>

    <h3 style="margin: 24px 0 12px; font-size:1rem; color:var(--text-muted); text-transform:uppercase; letter-spacing:1px;">Top 12 Largest Monthly Price Shocks</h3>
    <div style="overflow-x:auto;">
      <table class="data-table">
        <thead>
          <tr>
            <th>Month</th>
