          <canvas id="chartHist"></canvas>
        </div>
      </div>
      <div class="chart-card">
        <div class="chart-title">Statistical Summary</div>
        <div class="chart-subtitle">Key distributional metrics</div>
        <div style="padding:8px 0;">
          <table class="data-table">
            <tr><td><strong>All-time Range</strong></td><td>${price_range:.2f}/bbl</td></tr>
            <tr><td><strong>Mean/Median Gap</strong></td><td>${(overall_mean-overall_median):.2f} (mean exceeds median — right skew)</td></tr>
            <tr><td><strong>IQR (P25–P75)</strong></td><td>${p25:.2f} – ${p75:.2f}</td></tr>
            <tr><td><strong>Coefficient of Variation</strong></td><td>{(overall_std/overall_mean*100):.1f}% (σ/mean — very high dispersion)</td></tr>
            <tr><td><strong>Observations below $20</strong></td><td>{int((df.Price < 20).sum())} ({(df.Price < 20).mean()*100:.1f}%)</td></tr>
            <tr><td><strong>Observations above $80</strong></td><td>{int((df.Price >= 80).sum())} ({(df.Price >= 80).mean()*100:.1f}%)</td></tr>
            <tr><td><strong>Observations above $100</strong></td><td>{int((df.Price >= 100).sum())} ({(df.Price >= 100).mean()*100:.1f}%)</td></tr>
